app_css:
.tool-app-scopeguard { color: #3b0764; max-width: 860px; margin-inline:auto; }
.tool-app-scopeguard .sg-card { background: #fdf2f8; border: 1px solid #f9a8d4; border-radius: 12px; padding: 14px 16px; margin: 12px 0; }
.tool-app-scopeguard .sg-card h3 { margin: 0 0 4px; font-size: 13px; color: #9d174d; text-transform: uppercase; letter-spacing: 0.04em; }
.tool-app-scopeguard .sg-big { font-size: 32px; font-weight: 800; color: #be123c; }
.tool-app-scopeguard .sg-approved { color: #15803d; }
.tool-app-scopeguard .sg-sub { font-size: 13px; color: #831843; opacity: 0.85; }
.tool-app-scopeguard .sg-grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }
.tool-app-scopeguard .sg-grid3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-scopeguard .sg-wide { grid-column: 1 / -1; }
.tool-app-scopeguard label, .tool-app-scopeguard label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-scopeguard input[type="text"], .tool-app-scopeguard input[type="number"], .tool-app-scopeguard select { border: 1px solid #f0abfc; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-scopeguard .sg-btn { background: #DB2777; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-scopeguard .sg-btn:hover { background: #be185d; }
.tool-app-scopeguard .sg-btn-ghost { background: #fdf2f8; color: #DB2777; }
.tool-app-scopeguard .sg-btn-ghost:hover { background: #fce7f3; }
.tool-app-scopeguard .sg-btn-danger { background: none; color: #b91c1c; padding: 10px 12px; }
.tool-app-scopeguard .sg-tabs { display: flex; gap: 6px; margin: 14px 0; border-bottom: 2px solid #fbcfe8; }
.tool-app-scopeguard .sg-tab { background: none; border: none; border-bottom: 3px solid transparent; padding: 8px 12px; font-size: 14px; font-weight: 700; color: #9d174d; cursor: pointer; margin-bottom: -2px; }
.tool-app-scopeguard .sg-tab-on { border-bottom-color: #DB2777; color: #DB2777; }
.tool-app-scopeguard .sg-pane h4 { margin: 16px 0 8px; color: #831843; }
.tool-app-scopeguard .sg-list { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-scopeguard .sg-list li { display: flex; justify-content: space-between; align-items: center; gap: 10px; background: #fff7fb; border: 1px solid #fbcfe8; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-scopeguard .sg-list .sg-li-main { flex: 1; }
.tool-app-scopeguard .sg-list .sg-li-meta { font-size: 12px; color: #9d174d; white-space: nowrap; }
.tool-app-scopeguard .sg-status { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 3px 8px; border-radius: 999px; }
.tool-app-scopeguard .sg-st-pending { background: #fef3c7; color: #92400e; }
.tool-app-scopeguard .sg-st-approved { background: #dcfce7; color: #166534; }
.tool-app-scopeguard .sg-st-rejected { background: #fee2e2; color: #991b1b; }
.tool-app-scopeguard .sg-li-btns { display: flex; gap: 4px; }
.tool-app-scopeguard .sg-li-btns button { background: #fdf2f8; border: 1px solid #f0abfc; border-radius: 6px; font-size: 12px; font-weight: 700; color: #9d174d; padding: 4px 8px; cursor: pointer; }
.tool-app-scopeguard .sg-li-btns button.sg-on { background: #DB2777; border-color: #DB2777; color: #fff; }
.tool-app-scopeguard .sg-x { background: none; border: none; color: #b91c1c; font-size: 18px; cursor: pointer; }
.tool-app-scopeguard .sg-projects { display: flex; gap: 8px; align-items: center; margin: 12px 0; flex-wrap: wrap; }
.tool-app-scopeguard .sg-projects select { flex: 1; min-width: 180px; }
.tool-app-scopeguard .sg-addrow { display: flex; gap: 8px; margin: 8px 0; }
.tool-app-scopeguard .sg-addrow input { flex: 1; }
.tool-app-scopeguard .sg-revrow { display: flex; gap: 6px; }
.tool-app-scopeguard .sg-revrow input { flex: 1; }
.tool-app-scopeguard .sg-revrow .sg-btn { padding: 8px 12px; }
.tool-app-scopeguard .sg-actions { margin: 12px 0; }
.tool-app-scopeguard .sg-badge { background: #DB2777; color: #fff; border-radius: 999px; font-size: 11px; padding: 1px 8px; }
.tool-app-scopeguard .sg-draft { background: #fff; border: 1px solid #f0abfc; }
.tool-app-scopeguard .sg-draft pre { white-space: pre-wrap; font-family: inherit; font-size: 14px; margin: 0; }
.tool-app-scopeguard .sg-over { border-color: #ef4444 !important; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function num(v, d) { var n = parseFloat(v); return isFinite(n) ? n : (d || 0); }
  var root = $('toolAppRoot');
  var LS_KEY = 'toolapp-scopeguard-v1';
  function blankProject(name) {
    return { name: name || 'New project', client: '', price: 0, rate: 150,
      revLimit: 2, revUsed: 0, deliverables: [], asks: [] };
  }
  function getState() {
    try {
      var s = JSON.parse(localStorage.getItem(LS_KEY));
      if (s && s.projects && s.projects.length) return s;
    } catch (e) {}
    return { projects: [blankProject('My first project')], current: 0 };
  }
  function setState(s) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(s)); } catch (e) {}
  }
  function cur(s) { return s.projects[s.current]; }
  function fmtAsk(a, rate) {
    return esc(a.desc) + ' — ' + a.hours + 'h (' + money(a.hours * rate) + ')';
  }
  function refreshStats() {
    var s = getState(); var p = cur(s);
    var unbilled = 0, hours = 0, approved = 0, pending = 0;
    p.asks.forEach(function (a) {
      var cost = num(a.hours) * num(p.rate);
      if (a.status === 'approved') { approved += cost; }
      else if (a.status === 'pending') { unbilled += cost; hours += num(a.hours); pending++; }
    });
    $('sg-stat-unbilled').textContent = money(unbilled);
    $('sg-stat-hours').textContent = hours + ' hours across ' + pending + ' pending asks';
    $('sg-stat-approved').textContent = money(approved);
    $('sg-badge').textContent = pending ? pending : '';
    var over = num(p.revUsed) > num(p.revLimit);
    $('sg-revused').classList.toggle('sg-over', over);
  }
  function renderProjects() {
    var s = getState();
    var sel = $('sg-project');
    sel.innerHTML = '';
    s.projects.forEach(function (p, i) {
      var o = document.createElement('option');
      o.value = i; o.textContent = p.name || ('Project ' + (i + 1));
      sel.appendChild(o);
    });
    sel.value = s.current;
    var p = cur(s);
    $('sg-name').value = p.name || '';
    $('sg-client').value = p.client || '';
    $('sg-price').value = p.price;
    $('sg-rate').value = p.rate;
    $('sg-revlimit').value = p.revLimit;
    $('sg-revused').value = p.revUsed;
    renderDeliverables(); renderAsks(); refreshStats();
  }
  function saveProjectFromForm() {
    var s = getState(); var p = cur(s);
    p.name = $('sg-name').value || 'Untitled project';
    p.client = $('sg-client').value;
    p.price = num($('sg-price').value);
    p.rate = num($('sg-rate').value, 150);
    p.revLimit = Math.max(0, Math.round(num($('sg-revlimit').value)));
    p.revUsed = Math.max(0, Math.round(num($('sg-revused').value)));
    setState(s);
  }
  function renderDeliverables() {
    var s = getState(); var p = cur(s);
    var ul = $('sg-deliv'); ul.innerHTML = '';
    if (!p.deliverables.length) {
      var li0 = document.createElement('li'); li0.textContent = 'Nothing listed yet — write down everything the fixed price covers.'; ul.appendChild(li0); return;
    }
    p.deliverables.forEach(function (d, i) {
      var li = document.createElement('li');
      var span = document.createElement('span'); span.className = 'sg-li-main'; span.textContent = d;
      var x = document.createElement('button'); x.type = 'button'; x.className = 'sg-x';
      x.setAttribute('data-del', i); x.setAttribute('aria-label', 'Remove deliverable'); x.textContent = '×';
      li.appendChild(span); li.appendChild(x); ul.appendChild(li);
    });
  }
  function renderAsks() {
    var s = getState(); var p = cur(s);
    var ul = $('sg-asks'); ul.innerHTML = '';
    if (!p.asks.length) {
      var li0 = document.createElement('li'); li0.textContent = 'No asks logged. When the client asks for something extra, log it here before you reply.'; ul.appendChild(li0);
    } else {
      p.asks.forEach(function (a, i) {
        var li = document.createElement('li');
        var main = document.createElement('div'); main.className = 'sg-li-main';
        var strong = document.createElement('strong'); strong.textContent = a.desc;
        var meta = document.createElement('div'); meta.className = 'sg-li-meta';
        meta.textContent = a.hours + 'h × ' + money(p.rate) + '/hr = ' + money(num(a.hours) * num(p.rate));
        main.appendChild(strong); main.appendChild(meta);
        var status = document.createElement('span');
        status.className = 'sg-status sg-st-' + a.status;
        status.textContent = a.status;
        var btns = document.createElement('div'); btns.className = 'sg-li-btns';
        ['pending', 'approved', 'rejected'].forEach(function (st) {
          var b = document.createElement('button'); b.type = 'button';
          b.className = st === a.status ? 'sg-on' : '';
          b.setAttribute('data-ask', i); b.setAttribute('data-status', st);
          b.textContent = st === 'pending' ? 'Pending' : (st === 'approved' ? 'Approve' : 'Reject');
          btns.appendChild(b);
        });
        var x = document.createElement('button'); x.type = 'button'; x.className = 'sg-x';
        x.setAttribute('data-askdel', i); x.setAttribute('aria-label', 'Delete ask'); x.textContent = '×';
        li.appendChild(main); li.appendChild(status); li.appendChild(btns); li.appendChild(x);
        ul.appendChild(li);
      });
    }
    renderEmailSelect();
    refreshStats();
  }
  function renderEmailSelect() {
    var s = getState(); var p = cur(s);
    var sel = $('sg-email-ask'); sel.innerHTML = '';
    var pend = [];
    p.asks.forEach(function (a, i) { if (a.status === 'pending') pend.push([a, i]); });
    if (!pend.length) {
      var o = document.createElement('option'); o.textContent = 'No pending asks — log one first'; sel.appendChild(o);
    } else {
      pend.forEach(function (pair) {
        var o = document.createElement('option'); o.value = pair[1]; o.textContent = pair[0].desc + ' (' + money(num(pair[0].hours) * num(p.rate)) + ')';
        sel.appendChild(o);
      });
    }
    renderDraft();
  }
  function renderDraft() {
    var s = getState(); var p = cur(s);
    var sel = $('sg-email-ask');
    var idx = parseInt(sel.value, 10);
    var a = p.asks[idx];
    var greet = p.client ? 'Hi ' + p.client + ',' : 'Hi,';
    var proj = p.name ? ' on ' + p.name : '';
    var body;
    if (a) {
      body = greet + "\n" +
        'Happy to take this on' + proj + ' — quick note on the impact.\n' +
        'Adding "' + a.desc + '" is about ' + a.hours + ' extra hours, which comes to ' + money(num(a.hours) * num(p.rate)) + ' on top of the fixed price.\n' +
        'Want me to go ahead? I\'ll start as soon as you confirm.';
    } else {
      body = greet + "\n" +
        'Happy to take this on — quick note on the impact.\n' +
        'This falls outside the original scope, so it would be billed as a change order at ' + money(p.rate) + '/hr on top of the fixed price.\n' +
        'Want me to go ahead? I\'ll start as soon as you confirm.';
    }
    $('sg-draft').textContent = body;
  }
  function copyDraft() {
    var text = $('sg-draft').textContent;
    function done() { $('sg-copied').textContent = 'Copied.'; }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () { fallback(); });
    } else { fallback(); }
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); done(); } catch (e) {}
      document.body.removeChild(ta);
    }
  }
  root.addEventListener('input', function (e) {
    var id = e.target.id || '';
    if (id.indexOf('sg-name') === 0 || id.indexOf('sg-client') === 0 || id.indexOf('sg-price') === 0 ||
        id.indexOf('sg-rate') === 0 || id.indexOf('sg-revlimit') === 0 || id.indexOf('sg-revused') === 0) {
      saveProjectFromForm(); renderAsks();
    }
    if (id === 'sg-email-ask') renderDraft();
  });
  root.addEventListener('change', function (e) {
    if (e.target.id === 'sg-project') {
      var s = getState(); s.current = parseInt(e.target.value, 10) || 0; setState(s); renderProjects();
    }
  });
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains('sg-tab')) {
      var panes = root.querySelectorAll('.sg-tab');
      for (var i = 0; i < panes.length; i++) panes[i].classList.remove('sg-tab-on');
      t.classList.add('sg-tab-on');
      var p2 = root.querySelectorAll('.sg-pane');
      for (var j = 0; j < p2.length; j++) p2[j].hidden = true;
      $(t.getAttribute('data-tab')).hidden = false;
      if (t.getAttribute('data-tab') === 'sg-tab-email') renderDraft();
      return;
    }
    if (t.id === 'sg-newproject') {
      var s = getState();
      s.projects.push(blankProject('Project ' + (s.projects.length + 1)));
      s.current = s.projects.length - 1; setState(s); renderProjects(); return;
    }
    if (t.id === 'sg-delproject') {
      var s2 = getState();
      if (s2.projects.length <= 1) return;
      s2.projects.splice(s2.current, 1); s2.current = 0; setState(s2); renderProjects(); return;
    }
    if (t.id === 'sg-revplus') {
      var s3 = getState(); cur(s3).revUsed = num(cur(s3).revUsed) + 1;
      setState(s3); $('sg-revused').value = cur(s3).revUsed; refreshStats(); return;
    }
    if (t.id === 'sg-deliv-add') {
      var val = $('sg-deliv-in').value.trim(); if (!val) return;
      var s4 = getState(); cur(s4).deliverables.push(val); setState(s4);
      $('sg-deliv-in').value = ''; renderDeliverables(); return;
    }
    if (t.hasAttribute && t.hasAttribute('data-del')) {
      var s5 = getState(); cur(s5).deliverables.splice(parseInt(t.getAttribute('data-del'), 10), 1);
      setState(s5); renderDeliverables(); return;
    }
    if (t.id === 'sg-ask-add') {
      var desc = $('sg-ask-desc').value.trim(); if (!desc) { $('sg-ask-desc').focus(); return; }
      var s6 = getState();
      cur(s6).asks.push({ desc: desc, hours: num($('sg-ask-hours').value, 1), status: 'pending' });
      setState(s6); $('sg-ask-desc').value = ''; $('sg-ask-hours').value = '2';
      renderAsks(); return;
    }
    if (t.hasAttribute && t.hasAttribute('data-status')) {
      var s7 = getState();
      cur(s7).asks[parseInt(t.getAttribute('data-ask'), 10)].status = t.getAttribute('data-status');
      setState(s7); renderAsks(); return;
    }
    if (t.hasAttribute && t.hasAttribute('data-askdel')) {
      var s8 = getState(); cur(s8).asks.splice(parseInt(t.getAttribute('data-askdel'), 10), 1);
      setState(s8); renderAsks(); return;
    }
    if (t.id === 'sg-copy') { copyDraft(); return; }
  });
  renderProjects();
})();
